mapper.select:
SELECT COUNT(*)
FROM product_spu p
LEFT JOIN product_category c ON c.id = p.category_id


        AND p.category_id = #{categoryId}


        AND p.status = #{status}

SELECT p.id AS "id", p.category_id AS "categoryId", c.name AS "categoryName", p.name AS "name", p.subtitle AS "subtitle", p.brand_name AS "brandName", p.main_image_url AS "mainImageUrl", p.status AS "status", p.created_at AS "createdAt", p.updated_at AS "updatedAt" FROM product_spu p LEFT JOIN product_category c ON c.id = p.category_id
AND p.category_id = #{categoryId}
AND p.status = #{status}
ORDER BY p.created_at DESC, p.id DESC LIMIT #{limit} OFFSET #{offset}

WITH requested(id, sort_order) AS ( VALUES
(#{id}, #{index})
) SELECT p.id AS "id", p.category_id AS "categoryId", c.name AS "categoryName", p.name AS "name", p.subtitle AS "subtitle", p.brand_name AS "brandName", p.main_image_url AS "mainImageUrl", p.status AS "status", p.created_at AS "createdAt", p.updated_at AS "updatedAt" FROM requested r INNER JOIN product_spu p ON p.id = r.id LEFT JOIN product_category c ON c.id = p.category_id
AND p.category_id = #{categoryId}
AND p.status = #{status}
ORDER BY r.sort_order ASC

WITH requested(id, sort_order) AS ( VALUES
(#{id}, #{index})
), normalized_requested AS ( SELECT DISTINCT id, MIN(sort_order) AS sort_order FROM requested GROUP BY id ) SELECT p.id AS "id", p.category_id AS "categoryId", c.name AS "categoryName", p.name AS "name", p.subtitle AS "subtitle", p.brand_name AS "brandName", p.main_image_url AS "mainImageUrl", p.status AS "status", p.created_at AS "createdAt", p.updated_at AS "updatedAt" FROM normalized_requested r INNER JOIN product_spu p ON p.id = r.id LEFT JOIN product_category c ON c.id = p.category_id ORDER BY r.sort_order ASC

WITH requested(id) AS ( VALUES
(#{id})
), normalized_requested AS ( SELECT DISTINCT id FROM requested ) SELECT p.id AS "id", p.category_id AS "categoryId", c.name AS "categoryName", p.name AS "name", p.subtitle AS "subtitle", p.brand_name AS "brandName", p.main_image_url AS "mainImageUrl", p.status AS "status", p.created_at AS "createdAt", p.updated_at AS "updatedAt" FROM product_spu p INNER JOIN normalized_requested r ON r.id = p.category_id LEFT JOIN product_category c ON c.id = p.category_id ORDER BY p.id ASC LIMIT #{limit} OFFSET #{offset}

WITH requested(id) AS ( VALUES
(#{id})
), normalized_requested AS ( SELECT DISTINCT id FROM requested ) SELECT p.id FROM product_spu p INNER JOIN normalized_requested r ON r.id = p.category_id ORDER BY p.id ASC LIMIT #{limit} OFFSET #{offset}

WITH requested(id) AS ( VALUES
(#{id})
), normalized_requested AS ( SELECT DISTINCT id FROM requested ) SELECT COUNT(*) FROM product_spu p INNER JOIN normalized_requested r ON r.id = p.id

WITH requested(id) AS ( VALUES
(#{id})
), normalized_requested AS ( SELECT DISTINCT id FROM requested ) SELECT COUNT(*) FROM product_sku s INNER JOIN normalized_requested r ON r.id = s.id

WITH requested(id) AS ( VALUES
(#{id})
) SELECT encode(s.id, 'hex') AS "skuIdHex", to_base62(s.id) AS "skuId", s.sku_name AS "skuName", p.id AS "spuId", p.name AS "spuName" FROM product_sku s INNER JOIN requested r ON r.id = s.id LEFT JOIN product_spu p ON p.id = s.spu_id


WITH target_spu AS (
    SELECT id
    FROM product_spu
    WHERE id = #{spuId}
),
target_sku AS (
    SELECT s.id
    FROM product_sku s
    WHERE s.spu_id = #{spuId}
      AND s.id = #{skuId}
),
updated AS (
    UPDATE product_sku s
    SET status = #{status},
        updated_at = NOW()
    WHERE s.spu_id = #{spuId}
      AND s.id = #{skuId}
      AND EXISTS (SELECT 1 FROM target_sku)
    RETURNING s.id
)
SELECT EXISTS(SELECT 1 FROM target_spu) AS "spuExists",
       EXISTS(SELECT 1 FROM target_sku) AS "skuExists",
       (SELECT COUNT(*) FROM updated) AS "updatedCount"

WITH requested(id) AS ( VALUES
(#{id})
), normalized_requested AS ( SELECT DISTINCT id FROM requested ), target_spu AS ( SELECT id FROM product_spu WHERE id = #{spuId} ), target_sku AS ( SELECT s.id FROM product_sku s INNER JOIN normalized_requested r ON r.id = s.id WHERE s.spu_id = #{spuId} ), updated AS ( UPDATE product_sku s SET status = #{status}, updated_at = NOW() FROM target_sku t WHERE s.id = t.id AND s.spu_id = #{spuId} AND EXISTS (SELECT 1 FROM target_spu) AND (SELECT COUNT(*) FROM target_sku) = (SELECT COUNT(*) FROM normalized_requested) RETURNING s.id ) SELECT EXISTS(SELECT 1 FROM target_spu) AS "spuExists", (SELECT COUNT(*) FROM normalized_requested) AS "requestedCount", (SELECT COUNT(*) FROM target_sku) AS "matchedCount", (SELECT COUNT(*) FROM updated) AS "affectedCount"

WITH requested(id) AS ( VALUES
(#{id})
), normalized_requested AS ( SELECT DISTINCT id FROM requested ), target_spu AS ( SELECT id FROM product_spu WHERE id = #{spuId} ), target_sku AS ( SELECT s.id, s.sku_image_url FROM product_sku s INNER JOIN normalized_requested r ON r.id = s.id WHERE s.spu_id = #{spuId} ), deleted AS ( DELETE FROM product_sku s USING target_sku t WHERE s.id = t.id AND s.spu_id = #{spuId} AND EXISTS (SELECT 1 FROM target_spu) AND (SELECT COUNT(*) FROM target_sku) = (SELECT COUNT(*) FROM normalized_requested) RETURNING s.id, t.sku_image_url ) SELECT EXISTS(SELECT 1 FROM target_spu) AS "spuExists", (SELECT COUNT(*) FROM normalized_requested) AS "requestedCount", (SELECT COUNT(*) FROM target_sku) AS "matchedCount", (SELECT COUNT(*) FROM deleted) AS "affectedCount", COALESCE((SELECT jsonb_agg(encode(id, 'hex')) FROM deleted), '[]'::jsonb)::text AS "deletedSkuIdsJson", COALESCE(( SELECT jsonb_agg(url) FROM ( SELECT CASE WHEN jsonb_typeof(item.value) = 'string' THEN item.value #>> '{}' WHEN jsonb_typeof(item.value) = 'object' THEN item.value ->> 'url' ELSE NULL END AS url FROM deleted d CROSS JOIN LATERAL jsonb_array_elements( CASE WHEN jsonb_typeof(d.sku_image_url::jsonb) = 'array' THEN d.sku_image_url::jsonb ELSE '[]'::jsonb END ) AS item(value) ) raw WHERE url IS NOT NULL AND BTRIM(url) != '' ), '[]'::jsonb)::text AS "imageUrlsJson"

WITH requested(id) AS ( VALUES
(#{id})
), normalized_requested AS ( SELECT DISTINCT id FROM requested ), target_spu AS ( SELECT p.id FROM product_spu p INNER JOIN normalized_requested r ON r.id = p.id ), updated AS ( UPDATE product_spu p SET status = #{status}, updated_at = NOW() FROM target_spu t WHERE p.id = t.id AND p.status IS DISTINCT FROM #{status} AND (SELECT COUNT(*) FROM target_spu) = (SELECT COUNT(*) FROM normalized_requested) RETURNING p.id ) SELECT (SELECT COUNT(*) FROM normalized_requested) AS "requestedCount", (SELECT COUNT(*) FROM target_spu) AS "matchedCount", (SELECT COUNT(*) FROM updated) AS "affectedCount", COALESCE((SELECT jsonb_agg(id) FROM target_spu), '[]'::jsonb)::text AS "targetIdsJson"

WITH requested(id) AS ( VALUES
(#{id})
), normalized_requested AS ( SELECT DISTINCT id FROM requested ), target_spu AS ( SELECT p.id, p.main_image_url FROM product_spu p INNER JOIN normalized_requested r ON r.id = p.id ), delete_allowed AS ( SELECT (SELECT COUNT(*) FROM target_spu) = (SELECT COUNT(*) FROM normalized_requested) AS allowed ), target_sku AS ( SELECT s.id, s.sku_image_url FROM product_sku s INNER JOIN target_spu p ON p.id = s.spu_id ), target_detail AS ( SELECT d.id, d.image_urls, d.detail_image_urls FROM product_detail d INNER JOIN target_spu p ON p.id = d.spu_id ), raw_image_urls AS ( SELECT main_image_url AS url FROM target_spu UNION ALL SELECT CASE WHEN jsonb_typeof(item.value) = 'string' THEN item.value #>> '{}' WHEN jsonb_typeof(item.value) = 'object' THEN item.value ->> 'url' ELSE NULL END AS url FROM target_sku s CROSS JOIN LATERAL jsonb_array_elements( CASE WHEN jsonb_typeof(s.sku_image_url::jsonb) = 'array' THEN s.sku_image_url::jsonb ELSE '[]'::jsonb END ) AS item(value) UNION ALL SELECT CASE WHEN jsonb_typeof(item.value) = 'string' THEN item.value #>> '{}' WHEN jsonb_typeof(item.value) = 'object' THEN item.value ->> 'url' ELSE NULL END AS url FROM target_detail d CROSS JOIN LATERAL jsonb_array_elements( CASE WHEN jsonb_typeof(d.image_urls) = 'array' THEN d.image_urls ELSE '[]'::jsonb END ) AS item(value) UNION ALL SELECT CASE WHEN jsonb_typeof(item.value) = 'string' THEN item.value #>> '{}' WHEN jsonb_typeof(item.value) = 'object' THEN item.value ->> 'url' ELSE NULL END AS url FROM target_detail d CROSS JOIN LATERAL jsonb_array_elements( CASE WHEN jsonb_typeof(d.detail_image_urls) = 'array' THEN d.detail_image_urls ELSE '[]'::jsonb END ) AS item(value) ), image_urls AS ( SELECT DISTINCT url FROM raw_image_urls WHERE url IS NOT NULL AND BTRIM(url) != '' ), deleted_detail AS ( DELETE FROM product_detail d USING target_detail t, delete_allowed allow WHERE d.id = t.id AND allow.allowed RETURNING d.id ), deleted_sku AS ( DELETE FROM product_sku s USING target_sku t, delete_allowed allow WHERE s.id = t.id AND allow.allowed RETURNING s.id ), deleted_spu AS ( DELETE FROM product_spu p USING target_spu t, delete_allowed allow WHERE p.id = t.id AND allow.allowed RETURNING p.id ) SELECT (SELECT COUNT(*) FROM normalized_requested) AS "requestedCount", (SELECT COUNT(*) FROM target_spu) AS "matchedCount", (SELECT COUNT(*) FROM deleted_spu) AS "deletedSpuCount", (SELECT COUNT(*) FROM deleted_sku) AS "deletedSkuCount", (SELECT COUNT(*) FROM deleted_detail) AS "deletedDetailCount", COALESCE((SELECT jsonb_agg(id) FROM deleted_spu), '[]'::jsonb)::text AS "deletedIdsJson", COALESCE((SELECT jsonb_agg(encode(id, 'hex')) FROM deleted_sku), '[]'::jsonb)::text AS "deletedSkuIdsJson", COALESCE((SELECT jsonb_agg(url) FROM image_urls), '[]'::jsonb)::text AS "imageUrlsJson"
